class Solution {
public:
    bool canTransform(vector<int>& source, vector<int>& target) {
        if (source.size() != target.size()) return false;
        if (source.size() == 1) return source[0] == target[0];
        long long a = 0, b = 0;
        for (int x : source) a += x;
        for (int x : target) b += x;
        return a == b;
    }
};
